if (!initialized || Fs == 0 || channels <= 0) { FUZZ_BAIL(); }
int frame_sizes[6] = { Fs/400, Fs/200, Fs/100, Fs/50, Fs/25, (3*Fs)/50 };
int frame_size = frame_sizes[*FUZZ_PARAM(unsigned int) % 6u];
int do_plc = (int)(*FUZZ_PARAM(unsigned int) & 1u);
const unsigned char *data = NULL;
opus_int32 len = 0;
std::string payload = FUZZ_PARAM_STR();
if (!do_plc) {
    len = (opus_int32)((*FUZZ_PARAM(unsigned int) % (unsigned int)std::min<size_t>(payload.size(), 1500)) + 1u);
    if ((opus_int32)payload.size() < len) payload.resize((size_t)len);
    data = (const unsigned char*)payload.data();
}
std::vector<float> pcm((size_t)frame_size * (size_t)channels);
int fec = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int ret = opus_projection_decode_float(st, data, len, pcm.data(), frame_size, fec);
(void)ret;

// Only destroy decoders that were allocated by the create function.
const char *origin = FUZZ_GET_ATTR_STR(st, "origin");
int is_create = origin && origin[0] && (origin[0]=='c'); // "create"
if (!is_create) { FUZZ_BAIL(); }
opus_projection_decoder_destroy(st);
